refentry.refsect1:
&reftitle.description;
&style.oop; intstringmysqli_stmt->insert_id
&style.procedural;
intstringmysqli_stmt_insert_id mysqli_stmtstatement
Retourne l'ID généré par une requête INSERT ou UPDATE sur une table avec une colonne ayant l'attribut AUTO_INCREMENT. Dans le cas d'une requête INSERT multilignes, elle retourne la première valeur générée automatiquement qui a été insérée avec succès. Si LAST_INSERT_ID(expr) est utilisé pour définir la valeur de AUTO_INCREMENT, ou dans une requête UPDATE, la valeur de expr est retournée à la place.
Retourne 0 si la requête n'a pas modifié de valeur AUTO_INCREMENT.

  &reftitle.examples;

   Exemple avec mysqli_stmt::$insert_id
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$mysqli->query("CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = $mysqli->prepare("INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
$stmt->bind_param('sssi', $name, $countryCode, $district, $population);
$stmt->execute();

printf("Le nouvel enregistrement a l'ID %d.\n", $stmt->insert_id);


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$link = mysqli_connect("localhost", "my_user", "my_password", "world");

mysqli_query($link, "CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = mysqli_prepare($link, "INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
mysqli_stmt_bind_param($stmt, 'sssi', $name, $countryCode, $district, $population);
mysqli_stmt_execute($stmt);

printf("Le nouvel enregistrement a l'ID %d.\n", mysqli_stmt_insert_id($stmt));


   &examples.outputs;


Le nouvel enregistrement a l'ID 1.
